// Validates and PRICES the order on the server. Nothing the browser sends
// about price, total or availability is trusted.
function cleanPhone(raw) {
  var p = String(raw || '').replace(/[^0-9]/g, '');
  if (p === '') { return ''; }
  if (p.length === 11 && p.charAt(0) === '0') { return '91' + p.substring(1); }
  if (p.length === 10 && '6789'.indexOf(p.charAt(0)) !== -1) { return '91' + p; }
  if (p.length === 12 && p.substring(0, 2) === '91') { return p; }
  if (p.length >= 11 && p.length <= 15) { return p; }
  return '91' + p;
}
function norm(s) { return String(s || '').toLowerCase().replace(/\s+/g, ' ').trim(); }
function rs(n) { return 'Rs ' + Number(n || 0).toLocaleString('en-IN'); }
function bad(reason, code) { return [{ json: { invalid: true, reason: reason, code: code || 'invalid' } }]; }

var hook = $('PWA Webhook').first().json;
var d = hook.body || hook;
var ctx = $input.first().json || {};
if (Array.isArray(ctx)) { ctx = ctx[0] || {}; }

if (!Array.isArray(ctx.menu)) {
  return bad('We could not check the menu just now. Please try again in a minute.', 'unavailable');
}
if (ctx.is_open === false) {
  return bad('Sorry, Oceana Hotel is closed right now. We are open ' + (ctx.hours || '7:00 AM to 11:30 PM') +
             ' and are not taking orders until then.', 'closed');
}

var phone = cleanPhone(d.customer_phone || d.phone);
if (phone.length < 11 || phone.length > 15) {
  return bad('Please enter a valid WhatsApp number.', 'phone');
}
var name = String(d.customer_name || d.name || '').trim().slice(0, 60);
if (name.length < 2) { return bad('Please tell us your name.', 'name'); }

var raw = Array.isArray(d.items) ? d.items : [];
if (raw.length === 0) { return bad('Your cart is empty.', 'empty'); }
if (raw.length > 60) { return bad('That is too many different items for one order.', 'too_many'); }

var byNum = {};
var byName = {};
ctx.menu.forEach(function (m) { byNum[String(m.n)] = m; byName[norm(m.name)] = m; });

var priced = [];
var pos = {};
var soldOut = [];
var missing = [];
raw.forEach(function (i) {
  var m = byNum[String(i.item_number)] || byName[norm(i.name || i.item_name)];
  if (!m) { missing.push(String(i.name || i.item_name || 'an item')); return; }
  if (!m.available) { soldOut.push(m.name); return; }
  if (!(Number(m.price) > 0)) { missing.push(m.name); return; }
  var q = Math.round(Number(i.quantity));
  if (!(q > 0)) { return; }
  var key = String(m.n);
  if (Object.prototype.hasOwnProperty.call(pos, key)) {
    priced[pos[key]].quantity = Math.min(50, priced[pos[key]].quantity + q);
    return;
  }
  pos[key] = priced.length;
  priced.push({ item_number: m.n, name: m.name, quantity: Math.min(50, q), price: Number(m.price) });
});

if (soldOut.length) {
  return bad(soldOut.join(', ') + (soldOut.length > 1 ? ' are' : ' is') +
             ' sold out right now. Please remove ' + (soldOut.length > 1 ? 'them' : 'it') + ' and try again.', 'sold_out');
}
if (missing.length) {
  return bad(missing.join(', ') + ' cannot be ordered online right now. Please refresh the menu and try again.', 'unknown_item');
}
if (priced.length === 0) { return bad('Your cart is empty.', 'empty'); }

var total = priced.reduce(function (s, i) { return s + (i.price * i.quantity); }, 0);

var type = d.order_type || 'delivery';
if (['delivery', 'takeaway', 'dine-in'].indexOf(type) === -1) { type = 'delivery'; }

var address = String(d.address || '').trim().slice(0, 300);
var landmark = String(d.landmark || '').trim().slice(0, 120);
var pincode = String(d.pincode || '').trim();
if (type === 'delivery') {
  var min = Number(ctx.min_order || 200);
  if (total < min) {
    return bad('Delivery starts at ' + rs(min) + '. Add ' + rs(min - total) + ' more, or choose takeaway.', 'min_order');
  }
  if (address.length < 8) { return bad('We need your full address to deliver.', 'address'); }
  if (!/^\d{6}$/.test(pincode)) { return bad('Please enter your 6-digit pincode.', 'pincode'); }
  var pins = (ctx.pincodes || []).map(String);
  if (pins.length && pins.indexOf(pincode) === -1) {
    return bad('We do not deliver to ' + pincode + ' yet. Takeaway works though.', 'pincode');
  }
} else {
  address = ''; landmark = ''; pincode = '';
}

// order_number is omitted on purpose: the database assigns it.
return [{ json: {
  invalid: false,
  customer_phone: phone,
  customer_name: name,
  items: priced.map(function (i) { return i.name + ' x' + i.quantity; }).join(', '),
  raw_items: priced,
  total: total,
  order_type: type,
  address: address,
  landmark: landmark,
  city: ctx.city || 'Mangalore',
  pincode: pincode
} }];

function rs(n) { return 'Rs ' + Number(n || 0).toLocaleString('en-IN'); }

var created = $('Insert Order').first().json;
var rows = created.body !== undefined ? created.body : created;
var order = Array.isArray(rows) ? (rows[0] || {}) : (rows || {});
var d = $('Prepare Order').first().json;

var when = new Date(Date.now() + (5.5 * 60 * 60 * 1000));
var stamp = when.getUTCDate() + '/' + (when.getUTCMonth() + 1) + '/' + when.getUTCFullYear() +
            ' ' + when.getUTCHours() + ':' + String(when.getUTCMinutes()).padStart(2, '0');

var lines = d.raw_items.map(function (i) {
  var name = i.name || i.item_name || '';
  var qty = Number(i.quantity) || 1;
  var lt = (Number(i.price) || 0) * qty;
  return '- ' + name + ' x' + qty + (lt > 0 ? ('  ' + rs(lt)) : '');
}).join('\n');

var labels = { delivery: 'Delivery', takeaway: 'Takeaway', 'dine-in': 'Dine-in' };
var addr = '';
if (d.order_type === 'delivery' && d.address) {
  addr = '\n' + d.address + (d.landmark ? (', ' + d.landmark) : '') +
         (d.pincode ? (' - ' + d.pincode) : '');
}

var msg = '*OCEANA HOTEL - ORDER RECEIVED*\n' +
  '--------------------------------\n' +
  'Order *' + (order.order_number || '') + '*\n' + stamp + '\n\n' +
  lines + '\n\n*Total: ' + rs(d.total) + '*\n' +
  (labels[d.order_type] || d.order_type) + addr + '\n' +
  '--------------------------------\n' +
  'Thank you! We will keep you posted on your order.';

return [{ json: { phone: d.customer_phone, message: msg,
                  order_number: order.order_number || '' } }];

function rs(n){ return 'Rs ' + Number(n||0).toLocaleString('en-IN'); }
function esc(s){ return String(s==null?'':s)
  .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

function receiptHtml(o){
  var rows = o.items.map(function(i){
    var q = Number(i.quantity)||1;
    var lt = (Number(i.price)||0)*q;
    return '<tr><td class="it">'+esc(i.name)+'</td><td class="q">x'+q+'</td>'+
           '<td class="p">'+(lt>0?rs(lt):'-')+'</td></tr>';
  }).join('');
  var addr = o.address ? '<div class="ad">'+esc(o.address)+'</div>' : '';
  var css = '*{box-sizing:border-box}body{margin:0;padding:26px 18px;background:#EFEFEA;font-family:\'JetBrains Mono\',monospace;color:#1C1C1C}.paper{background:#FAFAF7;padding:28px 24px 30px;position:relative;box-shadow:0 2px 14px rgba(0,0,0,.10)}.paper:before,.paper:after{content:\'\';position:absolute;left:0;right:0;height:10px; background:repeating-linear-gradient(135deg,#FAFAF7 0 10px,transparent 10px 20px)}.paper:before{top:-9px;transform:scaleY(-1)}.paper:after{bottom:-9px}h1{margin:0;text-align:center;font-size:27px;letter-spacing:7px;color:#C0392B;font-weight:700}.sub{text-align:center;font-size:10.5px;letter-spacing:2.6px;color:#6B6B6B;margin-top:7px}.addr{text-align:center;font-size:10.5px;color:#8A8A8A;margin-top:6px;line-height:1.7}.dash{border-top:1.6px dashed #C9C9C4;margin:16px 0}.dot{border-top:1px dotted #D5D5D0;margin:13px 0}.pay{background:#C0392B;color:#fff;padding:13px 16px;margin:16px 0}.pay b{display:block;font-size:15px;letter-spacing:2.4px}.pay span{font-size:9.5px;letter-spacing:1.8px;opacity:.9}.num{text-align:center;font-size:22px;font-weight:700;letter-spacing:3px;margin-top:4px}.when{text-align:center;font-size:11px;color:#7A7A7A;margin-top:5px}.badge{border:1.6px solid #C0392B;color:#C0392B;text-align:center;padding:8px;font-size:11.5px; letter-spacing:2px;font-weight:700;margin:13px auto 0;max-width:280px}.lbl{font-size:9.5px;letter-spacing:2.4px;color:#A0A09A;margin:16px 0 8px}.kv{display:flex;justify-content:space-between;font-size:12px;padding:4px 0}.kv span:first-child{color:#8A8A8A;letter-spacing:1.4px;font-size:10px}.kv span:last-child{font-weight:700}.ad{font-size:11px;color:#5A5A5A;text-align:right;line-height:1.6;margin-top:2px}table{width:100%;border-collapse:collapse;margin-top:4px}th{font-size:9.5px;letter-spacing:2px;color:#A0A09A;text-align:left;padding-bottom:7px;font-weight:400}th.q,th.p{text-align:right}td{padding:8px 0;border-bottom:1px dotted #E2E2DD;font-size:12.5px}td.it{font-weight:700}td.q{text-align:right;color:#8A8A8A;width:48px}td.p{text-align:right;font-weight:700;width:92px}.total{border:2.2px solid #C0392B;display:flex;justify-content:space-between;align-items:center; padding:15px 17px;margin-top:18px}.total span{font-size:11.5px;letter-spacing:2.6px;color:#C0392B}.total b{font-size:25px;color:#C0392B}.note{text-align:center;font-size:10.5px;color:#7A7A7A;margin-top:13px}.ref{text-align:center;font-size:9.5px;letter-spacing:2.4px;color:#B5B5AE;margin:13px 0}.ty{text-align:center;font-size:12.5px;color:#4A4A4A;margin-top:4px;line-height:1.9}.ty b{color:#C0392B}';
  return '<html><head><meta charset="utf-8">'+
   '<link href="https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;700&display=swap" rel="stylesheet">'+
   '<style>'+css+'</style></head><body><div class="paper">'+
   '<h1>OCEANA</h1>'+
   '<div class="sub">INDIAN &amp; CHINESE RESTAURANT</div>'+
   '<div class="addr">Janapriya Complex, State Bank<br>Mangalore 575001<br>+91 96634 28354</div>'+
   '<div class="dash"></div>'+
   '<div class="pay"><b>CASH &middot; '+esc(o.type_label.toUpperCase())+'</b>'+
   '<span>'+(o.order_type==='delivery'?'PAY ON DELIVERY &middot; COD':'PAY AT COUNTER &middot; COD')+'</span></div>'+
   '<div class="dot"></div>'+
   '<div class="num">'+esc(o.order_number)+'</div>'+
   '<div class="when">'+esc(o.stamp)+'</div>'+
   '<div class="badge">'+esc(o.badge)+'</div>'+
   '<div class="lbl">CUSTOMER</div>'+
   '<div class="kv"><span>NAME</span><span>'+esc(o.customer_name||'Guest')+'</span></div>'+
   '<div class="kv"><span>PHONE</span><span>'+esc(o.phone)+'</span></div>'+
   '<div class="kv"><span>TYPE</span><span>'+esc(o.type_label)+'</span></div>'+ addr +
   '<div class="dot"></div>'+
   '<table><tr><th>ITEM</th><th class="q">QTY</th><th class="p">AMOUNT</th></tr>'+rows+'</table>'+
   '<div class="total"><span>TOTAL</span><b>'+rs(o.total)+'</b></div>'+
   '<div class="note">'+(o.order_type==='delivery'?'Please have exact change ready':'Pay at the counter')+'</div>'+
   '<div class="ref">'+esc(o.order_number)+' &middot; OCEANA HOTEL</div>'+
   '<div class="ty">Thank you for your order!<br><b>+91 96634 28354</b></div>'+
   '</div></body></html>';
}

function istStamp(){
  var w = new Date(Date.now() + (5.5*60*60*1000));
  var M = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  return w.getUTCDate()+' '+M[w.getUTCMonth()]+' '+w.getUTCFullYear()+
         ' \u00b7 '+w.getUTCHours()+':'+String(w.getUTCMinutes()).padStart(2,'0');
}
var LABELS = { delivery:'Delivery', takeaway:'Takeaway', 'dine-in':'Dine-in' };

var created = $('Insert Order').first().json;
var rows = created.body !== undefined ? created.body : created;
var order = Array.isArray(rows) ? (rows[0] || {}) : (rows || {});
var d = $('Prepare Order').first().json;
var addr = '';
if (d.order_type === 'delivery' && d.address) {
  addr = d.address + (d.landmark ? ', ' + d.landmark : '') + (d.pincode ? ' - ' + d.pincode : '');
}
var html = receiptHtml({
  order_number: order.order_number || '', stamp: istStamp(), badge: 'ORDER RECEIVED',
  customer_name: d.customer_name, phone: d.customer_phone,
  order_type: d.order_type, type_label: LABELS[d.order_type] || d.order_type,
  address: addr, items: d.raw_items, total: d.total });
return [{ json: { html: html, order_number: order.order_number || '', phone: d.customer_phone } }];

var inv = $('Build Invoice HTML').first().json;
var img = $input.first().json.url;
var caption = 'Thanks! Your order ' + inv.order_number + ' is in. We will confirm it in a moment.';
return [{ json: { phone: inv.phone, outgoing: {
  type: 'image', image: { link: img, caption: caption } } } }];

// Either the image branch or the text branch ran, never both. Read whichever
// exists so the chat log is correct on both paths.
var phone = '', content = '';
try { var inv = $('Build Invoice HTML').first().json; phone = inv.phone; } catch (e) {}
try {
  var img = $('Prepare Invoice Image').first().json;
  if (img && img.outgoing) {
    phone = img.phone || phone;
    content = '[invoice image] ' + ((img.outgoing.image && img.outgoing.image.caption) || '');
  }
} catch (e) {}
if (content === '') {
  try { var t = $('Build WhatsApp Confirmation').first().json;
        phone = t.phone || phone; content = t.message || ''; } catch (e) {}
}
if (content === '') { content = 'Order confirmation sent'; }
return [{ json: { phone: phone, content: content } }];
